package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseO2MigrationTest extends MigrationTestSupport {
 @Test void existingCatalogAndSavesSurviveButUnverifiedClaimsAreNotPublished(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_o2_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("62").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));try{UUID fixtureUser=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES ('o2-legacy-author@example.test','synthetic','ACTIVE') RETURNING id",UUID.class);db.update("INSERT INTO professional_profiles(user_id,professional_type) VALUES (?,'OTHER')",fixtureUser);db.update("INSERT INTO professional_articles(author_id,title,summary,topic,read_time_minutes,status,evidence_level,published_at) VALUES (?,'Synthetic legacy article','Persisted historical text','Education',1,'PUBLISHED','Unverified synthetic reviewer',CURRENT_TIMESTAMP)",fixtureUser);db.update("INSERT INTO media_recommendations(title,media_kind,release_year,duration_label,theme,description,discussion_prompt,recommended_by,accent,soft_accent) VALUES ('Synthetic legacy film','MOVIE',2020,'1h','Planning','Preserved legacy metadata','Optional prompt','Unverified synthetic reviewer','#000000','#ffffff')");var articles=db.queryForList("SELECT to_jsonb(t)::text AS record FROM professional_articles t ORDER BY id");var media=db.queryForList("SELECT to_jsonb(t)::text AS record FROM media_recommendations t ORDER BY id");assertThat(articles).isNotEmpty();assertThat(media).isNotEmpty();UUID user=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES ('o2-upgrade@example.test','synthetic','ACTIVE') RETURNING id",UUID.class);UUID article=db.queryForObject("SELECT id FROM professional_articles ORDER BY id LIMIT 1",UUID.class);db.update("INSERT INTO article_saves(user_id,article_id) VALUES (?,?)",user,article);var f=Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("64").load();f.migrate();f.validate();f.migrate();assertThat(db.queryForList("SELECT to_jsonb(t)::text AS record FROM professional_articles t ORDER BY id")).isEqualTo(articles);assertThat(db.queryForList("SELECT to_jsonb(t)::text AS record FROM media_recommendations t ORDER BY id")).isEqualTo(media);assertThat(db.queryForObject("SELECT count(*) FROM article_saves WHERE user_id=?",Integer.class,user)).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM growth_resources",Integer.class)).isEqualTo(articles.size()+media.size());assertThat(db.queryForObject("SELECT count(*) FROM growth_resources WHERE growth_resource_available(id)",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM educational_permissions",Integer.class)).isZero();}finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}}
}
